package findu.backend.report.entity; import findu.backend.global.entity.BaseEntity; import findu.backend.user.entity.User; import jakarta.persistence.*; import lombok.*; @Entity @Getter @Builder @NoArgsConstructor(access=AccessLevel.PROTECTED) @AllArgsConstructor @Table(name="reports") public class Report extends BaseEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="reporter_id")User reporter;@Column(nullable=false,length=30)String targetType;@Column(nullable=false)Long targetId;@Column(nullable=false,length=100)String reason;@Column(columnDefinition="TEXT")String description;@Enumerated(EnumType.STRING)@Column(nullable=false)Status status;public enum Status{PENDING,RESOLVED,REJECTED}public void updateStatus(Status s){status=s;}}
